tools:
[
  {
    "function": {
      "description": "Ask the user a question and wait for their answer. Use when blocked on a human decision — never guess. Optional named args: detail (context shown under the question), options (a JSON array of suggested answers), multi (`true` lets the user pick several options).",
      "name": "ask-user",
      "parameters": {
        "properties": {
          "detail": {
            "type": "string"
          },
          "multi": {
            "type": "string"
          },
          "options": {
            "type": "string"
          },
          "question": {
            "type": "string"
          }
        },
        "required": [
          "question"
        ],
        "type": "object"
      }
    },
    "type": "function"
  },
  {
    "function": {
      "description": "Set this session's durable objective and keep working toward it across turns. Positional args: <objective> <max_rounds>. Only the user can create or change a goal; each round is a full turn, so ask before setting one.",
      "name": "create-goal",
      "parameters": {
        "properties": {
          "max_rounds": {
            "type": "string"
          },
          "objective": {
            "type": "string"
          }
        },
        "required": [
          "objective",
          "max_rounds"
        ],
        "type": "object"
      }
    },
    "type": "function"
  },
  {
    "function": {
      "description": "Present the finished plan (markdown) for user approval. Only call in plan mode; ends the turn on approval.",
      "name": "exit-plan-mode",
      "parameters": {
        "properties": {
          "plan": {
            "type": "string"
          }
        },
        "required": [
          "plan"
        ],
        "type": "object"
      }
    },
    "type": "function"
  },
  {
    "function": {
      "description": "Read this session's goal: objective, phase, round count and the current revision (which `update-goal` requires). No arguments.",
      "name": "get-goal",
      "parameters": {
        "properties": {},
        "required": [],
        "type": "object"
      }
    },
    "type": "function"
  },
  {
    "function": {
      "description": "Run a short Rhai program that calls the other tools and prints what matters. Only what the program prints or returns enters the conversation.",
      "name": "run-code",
      "parameters": {
        "properties": {
          "code": {
            "type": "string"
          },
          "description": {
            "type": "string"
          }
        },
        "required": [
          "code"
        ],
        "type": "object"
      }
    },
    "type": "function"
  },
  {
    "function": {
      "description": "Replace the session todo list with a JSON array of {content, status}. Shows as a checklist in the UI.",
      "name": "todo-write",
      "parameters": {
        "properties": {
          "items": {
            "type": "string"
          }
        },
        "required": [
          "items"
        ],
        "type": "object"
      }
    },
    "type": "function"
  },
  {
    "function": {
      "description": "Change the goal's phase. Positional args: <revision> <action> <note>, where action is pause | resume | complete | block. The revision must match the goal's current one — read it with get-goal first.",
      "name": "update-goal",
      "parameters": {
        "properties": {
          "action": {
            "type": "string"
          },
          "note": {
            "type": "string"
          },
          "revision": {
            "type": "string"
          }
        },
        "required": [
          "revision",
          "action",
          "note"
        ],
        "type": "object"
      }
    },
    "type": "function"
  }
]

